import * as THREE from 'three';
import { OrbitControls } from './vendor/OrbitControls.js';
import { buildEngine, componentData } from './model.js';
const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const state={power:55,playing:!reduced,cutaway:true,airflow:true,explode:false,orbit:false,selected:0};
const scene=new THREE.Scene();scene.background=new THREE.Color('#edf0f4');const camera=new THREE.PerspectiveCamera(33,1,.1,120);
let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true});}catch(error){$('loading').textContent='This study needs WebGL. Enable hardware acceleration or try a browser with 3D graphics support.';document.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);throw error;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;renderer.outputColorSpace=THREE.SRGBColorSpace;$('viewport').appendChild(renderer.domElement);$('loading').remove();
scene.add(new THREE.HemisphereLight(0xf2f7ff,0x748292,2.4));function light(color,intensity,x,y,z){const l=new THREE.DirectionalLight(color,intensity);l.position.set(x,y,z);scene.add(l);return l;}const key=light(0xffffff,3.4,-3,10,6);key.castShadow=true;key.shadow.mapSize.set(2048,2048);Object.assign(key.shadow.camera,{left:-10,right:10,top:8,bottom:-8});key.shadow.bias=-.0004;light(0xc6ddff,2.8,2,3,-8);light(0xffffff,2.5,-8,2,-2);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(100,100),new THREE.ShadowMaterial({opacity:.14}));floor.rotation.x=-Math.PI/2;floor.position.y=-2.11;floor.receiveShadow=true;scene.add(floor);
const model=buildEngine();scene.add(model.root);
const controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,0,0);controls.enableDamping=true;controls.dampingFactor=.065;controls.minDistance=4;controls.maxDistance=48;controls.autoRotateSpeed=.5;controls.maxPolarAngle=Math.PI*.88;controls.enablePan=true;
function cameraPose(mode='three-quarter'){const directions={'three-quarter':[-.64,.36,.88],side:[0,.14,1],front:[-1,.025,.025],rear:[1,.09,.08]};const direction=new THREE.Vector3(...directions[mode]).normalize();const extent=state.explode?18:11.4;const width=mode==='front'||mode==='rear'?5.4:extent;const distance=Math.max(5.4,width/camera.aspect)/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))*1.04;controls.target.set(state.explode?.2:0,0,0);camera.position.copy(controls.target).addScaledVector(direction,distance);controls.update();$('camera').value=mode;}
function resize(){const r=$('viewport').getBoundingClientRect();if(!r.width||!r.height)return;camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height);cameraPose($('camera').value);}new ResizeObserver(resize).observe($('viewport'));
function setPlaying(value){state.playing=value;$('play').textContent=value?'Ⅱ Pause':'▶ Play';$('play').setAttribute('aria-label',value?'Pause animation':'Play animation');}
function setPower(value){if(!Number.isFinite(value))throw Error('Power must be a number');state.power=Math.round(Math.max(0,Math.min(100,value)));$('power').value=state.power;$('power-value').textContent=state.power;document.querySelectorAll('[data-power]').forEach(b=>b.classList.toggle('selected',+b.dataset.power===state.power));}
function syncView(){for(const id of ['airflow','explode','orbit'])$(id).checked=state[id];$('cutaway').classList.toggle('active',state.cutaway);$('complete').classList.toggle('active',!state.cutaway);$('cutaway').setAttribute('aria-pressed',String(state.cutaway));$('complete').setAttribute('aria-pressed',String(!state.cutaway));$('flow-note').hidden=!state.explode;$('view-caption').textContent='TURBOFAN / '+(state.explode?'EXPLODED ASSEMBLY':state.cutaway?'CUTAWAY':'COMPLETE');controls.autoRotate=state.orbit;model.update(0,state);}
function selectPart(id){if(!Number.isInteger(id)||id<0||id>=componentData.length)throw Error('Component must be 0–6');state.selected=id;const c=componentData[id];$('part-counter').textContent=String(id+1).padStart(2,'0');$('part-title').textContent=c.name;$('part-category').textContent=c.category;$('part-description').textContent=c.description;$('part-function').textContent=c.job;$('part-energy').textContent=c.energy;$('part-label').textContent=String(id+1).padStart(2,'0')+' — '+c.name;model.select(id);document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('active',+b.dataset.part===id);b.setAttribute('aria-pressed',String(+b.dataset.part===id));});}
componentData.forEach((c,id)=>{const b=document.createElement('button');b.dataset.part=id;b.innerHTML='<span>'+String(id+1).padStart(2,'0')+'</span><strong>'+c.short+'</strong>';b.onclick=()=>selectPart(id);$('stage-rail').appendChild(b);});
$('power').oninput=e=>setPower(+e.target.value);document.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>setPower(+b.dataset.power));$('play').onclick=()=>setPlaying(!state.playing);$('step').onclick=()=>{setPlaying(false);model.update(.12,{...state,playing:true});};$('cutaway').onclick=()=>{state.cutaway=true;syncView();};$('complete').onclick=()=>{state.cutaway=false;syncView();};for(const id of ['airflow','explode','orbit'])$(id).onchange=e=>{state[id]=e.target.checked;syncView();if(id==='explode')cameraPose($('camera').value);};$('camera').onchange=e=>cameraPose(e.target.value);$('home').onclick=()=>cameraPose();$('previous').onclick=()=>selectPart((state.selected+6)%7);$('next').onclick=()=>selectPart((state.selected+1)%7);
$('reset').onclick=()=>{Object.assign(state,{power:55,playing:!reduced,cutaway:true,airflow:true,explode:false,orbit:false,selected:0});setPower(55);setPlaying(!reduced);selectPart(0);syncView();cameraPose();};
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;renderer.domElement.addEventListener('pointerdown',e=>{down=[e.clientX,e.clientY];});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>6)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const active=model.pickables.filter(m=>{for(let p=m;p;p=p.parent)if(!p.visible)return false;return true;});const hits=ray.intersectObjects(active,false);if(hits.length)selectPart(hits[0].object.userData.part);});
renderer.domElement.addEventListener('webglcontextlost',event=>{event.preventDefault();setPlaying(false);const notice=document.createElement('div');notice.id='loading';notice.textContent='3D graphics paused. Reload the page to restore the view.';$('viewport').appendChild(notice);});
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON','A'].includes(document.activeElement.tagName)){e.preventDefault();setPlaying(!state.playing);}});
selectPart(0);setPlaying(state.playing);syncView();resize();let previous=performance.now();function frame(now){if(window.__studyHidden){previous=now;requestAnimationFrame(frame);return;}const dt=Math.min(.05,(now-previous)/1000);previous=now;model.update(dt,state);controls.update();renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'configure_turbofan_study',description:'Change the visible turbofan study controls and inspect a component.',inputSchema:{type:'object',properties:{power:{type:'number',minimum:0,maximum:100},playing:{type:'boolean'},cutaway:{type:'boolean'},airflow:{type:'boolean'},explode:{type:'boolean'},component:{type:'integer',minimum:1,maximum:7}},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object')throw Error('Expected settings');for(const k of Object.keys(input))if(!['power','playing','cutaway','airflow','explode','component'].includes(k))throw Error('Unknown setting');if(input.power!==undefined&&(!Number.isFinite(input.power)||input.power<0||input.power>100))throw Error('Power must be 0–100');if(input.component!==undefined&&(!Number.isInteger(input.component)||input.component<1||input.component>7))throw Error('Component must be 1–7');for(const k of ['playing','cutaway','airflow','explode'])if(input[k]!==undefined&&typeof input[k]!=='boolean')throw Error(k+' must be boolean');if(input.power!==undefined)setPower(input.power);if(input.playing!==undefined)setPlaying(input.playing);if(input.component!==undefined)selectPart(input.component-1);for(const k of ['cutaway','airflow','explode'])if(input[k]!==undefined)state[k]=input[k];syncView();if(input.explode!==undefined)cameraPose($('camera').value);return {power:state.power,playing:state.playing,cutaway:state.cutaway,airflow:state.airflow,explode:state.explode,component:state.selected+1};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
